import React, { useEffect, useState } from "react";
import axios from "axios";
import "./ViewTasks.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import StudentSidebar from "../components/StudentSidebar";

const ViewTasks = () => {
  const user = JSON.parse(localStorage.getItem("users"));
  const [milestones, setMilestones] = useState([]);
  const [group, setGroup] = useState(null);
  const [student, setStudent] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [newMilestone, setNewMilestone] = useState("");
  const [newTask, setNewTask] = useState({
    title: "",
    creator: user?.username || "",
    status: "Pending",
    deadline: "",
  });

  useEffect(() => {
    const fetchGroupData = async () => {
      if (!user || user.role !== "student") {
        setError("Access denied. Only students can view this page.");
        setLoading(false);
        return;
      }

      try {
        const studentRes = await axios.get(`http://localhost:5000/api/student/user/${user._id}`);
        const studentData = studentRes.data;
        setStudent(studentData);

        if (!studentData.isGrouped) {
          setError("You are not assigned to any group.");
          setLoading(false);
          return;
        }

        const groupRes = await axios.get(`http://localhost:5000/api/group/regno/${studentData.regNo}`);
        setGroup(groupRes.data);

        const milestoneRes = await axios.get(
          `http://localhost:5000/api/milestone?projectID=${groupRes.data.projectID}`
        );
        const allMilestones = await Promise.all(
          milestoneRes.data.map(async (ms) => {
            const taskRes = await axios.get(`http://localhost:5000/api/task?milestoneId=${ms._id}`);
            return { ...ms, tasks: taskRes.data };
          })
        );
        setMilestones(allMilestones);
      } catch (err) {
        console.error(err);
        setError("Failed to load data.");
      } finally {
        setLoading(false);
      }
    };

    fetchGroupData();
  }, [user]);

  const handleAddMilestone = async () => {
    if (!newMilestone.trim() || !group) return;

    try {
      const res = await axios.post("http://localhost:5000/api/milestone", {
        projectID: group.projectID,
        title: newMilestone,
        dueDate: new Date(),
        status: "Pending",
      });

      setMilestones([...milestones, { ...res.data, tasks: [] }]);
      setNewMilestone("");
    } catch (err) {
      alert("Failed to add milestone.");
    }
  };

  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim() || !user?._id) return;

    try {
      const res = await axios.post("http://localhost:5000/api/task", {
        milestoneId,
        title: newTask.title,
        status: "Pending",
        uploadedBy: user._id,
      });

      setMilestones((prev) =>
        prev.map((ms) =>
          ms._id === milestoneId ? { ...ms, tasks: [...ms.tasks, res.data] } : ms
        )
      );

      setNewTask({ title: "", creator: user.username, status: "Pending", deadline: "" });
    } catch (err) {
      alert("Failed to add task.");
    }
  };

  const handleUpdateTaskStatus = (milestoneId, taskId) => {
    setMilestones((prevMilestones) =>
      prevMilestones.map((ms) =>
        ms._id === milestoneId
          ? {
              ...ms,
              tasks: ms.tasks.map((task) =>
                task._id === taskId
                  ? {
                      ...task,
                      status: "Completed",
                      completedBy: student.studentName,
                      completedAt: new Date().toLocaleString(),
                    }
                  : task
              ),
            }
          : ms
      )
    );
    // You can add a backend PATCH here
  };

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="tasks-title">Manage Milestones and Tasks</h1>

          {loading ? (
            <p>Loading...</p>
          ) : error ? (
            <div className="error-message">
              <p>{error}</p>
            </div>
          ) : (
            <>
              {/* Input Field for Adding a Milestone */}
              <div className="milestone-section">
                <input
                  type="text"
                  value={newMilestone}
                  onChange={(e) => setNewMilestone(e.target.value)}
                  placeholder="Add a new milestone"
                />
                <button onClick={handleAddMilestone}>Add Milestone</button>
              </div>

              {/* List of Milestones with Tasks */}
              <div className="milestone-list">
                {milestones.map((milestone) => (
                  <div key={milestone._id} className="milestone-item">
                    <h2>{milestone.title}</h2>
                    <p>Due Date: {new Date(milestone.dueDate).toLocaleDateString()}</p>

                    {/* Input Fields for Adding a Task */}
                    <div className="task-section">
                      <input
                        type="text"
                        value={newTask.title}
                        onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
                        placeholder="Task title"
                      />
                      <button
                        className="task-button"
                        onClick={() => handleAddTask(milestone._id)}
                      >
                        Add Task
                      </button>

                      {/* Task Table */}
                      <div className="tasks-table">
                        <table>
                          <thead>
                            <tr>
                              <th>Task</th>
                              <th>Status</th>
                              <th>Uploaded By</th>
                              <th>Completed By</th>
                              <th>Actions</th>
                            </tr>
                          </thead>
                          <tbody>
                            {milestone.tasks.map((task) => (
                              <tr key={task._id}>
                                <td>{task.title}</td>
                                <td>{task.status}</td>
                                <td>{task.uploadedBy}</td>
                                <td>{task.completedBy || "N/A"}</td>
                                <td>
                                  {task.status !== "Completed" && (
                                    <button
                                      className="mark-completed-button"
                                      onClick={() =>
                                        handleUpdateTaskStatus(milestone._id, task._id)
                                      }
                                    >
                                      Mark as Completed
                                    </button>
                                  )}
                                </td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
